export function generateSteps(input) {
  const arr = [...input];
  const n = arr.length;

  if (n === 0) return [];

  const steps = [];
  let comparisons = 0;
  let moves = 0;

  // Find maximum number to determine number of digits
  const maxNum = Math.max(...arr);
  const numDigits = maxNum.toString().length;

  steps.push({
    type: 'info',
    msg: `Max number: ${maxNum} has ${numDigits} digits. Will do ${numDigits} passes.`,
    indices: [],
    arr: [...arr],
    pass: 0,
    digit: null,
    buckets: null,
    comparisons,
    moves,
  });

  // Radix sort - process each digit position (right to left)
  let digitPosition = 1;
  let passNum = 1;

  for (let pass = 0; pass < numDigits; pass++) {
    steps.push({
      type: 'pass_start',
      msg: `Pass ${passNum}: Sorting by digit position (${digitPosition})`,
      indices: [],
      arr: [...arr],
      pass: passNum,
      digit: digitPosition,
      buckets: null,
      comparisons,
      moves,
    });

    // Create buckets (0-9)
    const buckets = Array.from({ length: 10 }, () => []);

    // Distribute numbers into buckets based on digit
    for (let i = 0; i < n; i++) {
      const digit = Math.floor(arr[i] / digitPosition) % 10;
      buckets[digit].push(arr[i]);
      comparisons++;

      steps.push({
        type: 'distribute',
        msg: `Number ${arr[i]}: digit = ${digit}. Placing in bucket ${digit}`,
        indices: [i],
        arr: [...arr],
        pass: passNum,
        digit: digitPosition,
        buckets: buckets.map(b => [...b]),
        comparisons,
        moves,
      });
    }

    // Collect from buckets in order
    let newArrIdx = 0;
    for (let bucketNum = 0; bucketNum < 10; bucketNum++) {
      for (let num of buckets[bucketNum]) {
        arr[newArrIdx] = num;
        moves++;
        newArrIdx++;

        steps.push({
          type: 'collect',
          msg: `Collecting from buckets: placing ${num} at index ${newArrIdx - 1}`,
          indices: [newArrIdx - 1],
          arr: [...arr],
          pass: passNum,
          digit: digitPosition,
          buckets: buckets.map(b => [...b]),
          comparisons,
          moves,
        });
      }
    }

    steps.push({
      type: 'pass_complete',
      msg: `Pass ${passNum} complete. Array after digit ${digitPosition}: ${arr.join(', ')}`,
      indices: [],
      arr: [...arr],
      pass: passNum,
      digit: digitPosition,
      buckets: null,
      comparisons,
      moves,
    });

    digitPosition *= 10;
    passNum++;
  }

  steps.push({
    type: 'complete',
    msg: `✅ Radix Sort Complete! Final array: ${arr.join(', ')}`,
    indices: [],
    arr: [...arr],
    pass: 0,
    digit: null,
    buckets: null,
    comparisons,
    moves,
  });

  return steps;
}
